import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Linux 上检查用户所属组 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上检查用户所属组 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上检查用户所属组 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上检查用户所属组 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180619 How To Check Which Groups A User Belongs To On Linux","title":"如何在 Linux 上检查用户所属组","tag":"201807","desc":""},"relativePath":"201807/20180619 How To Check Which Groups A User Belongs To On Linux.md","filePath":"[post].md"}'),g={name:"201807/20180619 How To Check Which Groups A User Belongs To On Linux.md"};function h(c,s,k,u,b,y){const e=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上检查用户所属组" tabindex="-1">如何在 Linux 上检查用户所属组 <a class="header-anchor" href="#如何在-linux-上检查用户所属组" aria-label="Permalink to “如何在 Linux 上检查用户所属组”">​</a></h1><p>将用户添加到现有组是 Linux 管理员的常规活动之一。这是一些在大环境中工作的管理员的日常活动。</p><p>甚至我会因为业务需求而在我的环境中每天都在进行这样的活动。它是帮助你识别环境中现有组的重要命令之一。</p><p>此外，这些命令还可以帮助你识别用户所属的组。所有用户都列在 <code>/etc/passwd</code> 中，组列在 <code>/etc/group</code> 中。</p><p>无论我们使用什么命令，都将从这些文件中获取信息。此外，每个命令都有其独特的功能，可帮助用户单独获取所需的信息。</p><h3 id="什么是-etc-passwd" tabindex="-1">什么是 /etc/passwd？ <a class="header-anchor" href="#什么是-etc-passwd" aria-label="Permalink to “什么是 /etc/passwd？”">​</a></h3><p><code>/etc/passwd</code> 是一个文本文件，其中包含登录 Linux 系统所必需的每个用户信息。它维护有用的用户信息，如用户名、密码、用户 ID、组 ID、用户 ID 信息、家目录和 shell。passwd 每行包含了用户的详细信息，共有如上所述的 7 个字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/passwd</span></span>
<span class="line"><span>daygeek:x:1000:1000:daygeek,,,:/home/daygeek:/bin/bash</span></span></code></pre></div><h3 id="什么是-etc-group" tabindex="-1">什么是 /etc/group？ <a class="header-anchor" href="#什么是-etc-group" aria-label="Permalink to “什么是 /etc/group？”">​</a></h3><p><code>/etc/group</code> 是一个文本文件，用于定义用户所属的组。我们可以将多个用户添加到单个组中。它允许用户访问其他用户文件和文件夹，因为 Linux 权限分为三类：用户、组和其他。它维护有关组的有用信息，例如组名、组密码，组 ID（GID）和成员列表。每个都在一个单独的行。组文件每行包含了每个组的详细信息，共有 4 个如上所述字段。</p><p>这可以通过使用以下方法来执行。</p><ul><li><code>groups</code>： 显示一个组的所有成员。</li><li><code>id</code>： 打印指定用户名的用户和组信息。</li><li><code>lid</code>： 显示用户的组或组的用户。</li><li><code>getent</code>： 从 Name Service Switch 库中获取条目。</li><li><code>grep</code>： 代表“<ruby>全局正则表达式打印<rt>global regular expression print</rt></ruby>”，它能打印匹配的模式。</li></ul><h3 id="什么是-groups-命令" tabindex="-1">什么是 groups 命令？ <a class="header-anchor" href="#什么是-groups-命令" aria-label="Permalink to “什么是 groups 命令？”">​</a></h3><p><code>groups</code> 命令打印每个给定用户名的主要组和任何补充组的名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups daygeek</span></span>
<span class="line"><span>daygeek : daygeek adm cdrom sudo dip plugdev lpadmin sambashare</span></span></code></pre></div><p>如果要检查与当前用户关联的组列表。只需运行 <code>groups</code> 命令，无需带任何用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups</span></span>
<span class="line"><span>daygeek adm cdrom sudo dip plugdev lpadmin sambashare</span></span></code></pre></div><h3 id="什么是-id-命令" tabindex="-1">什么是 id 命令？ <a class="header-anchor" href="#什么是-id-命令" aria-label="Permalink to “什么是 id 命令？”">​</a></h3><p>id 代表 “<ruby>身份<rt>identity</rt></ruby>”。它打印真实有效的用户和组 ID。打印指定用户或当前用户的用户和组信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id daygeek</span></span>
<span class="line"><span>uid=1000(daygeek) gid=1000(daygeek) groups=1000(daygeek),4(adm),24(cdrom),27(sudo),30(dip),46(plugdev),118(lpadmin),128(sambashare)</span></span></code></pre></div><p>如果要检查与当前用户关联的组列表。只运行 <code>id</code> 命令，无需带任何用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id</span></span>
<span class="line"><span>uid=1000(daygeek) gid=1000(daygeek) groups=1000(daygeek),4(adm),24(cdrom),27(sudo),30(dip),46(plugdev),118(lpadmin),128(sambashare)</span></span></code></pre></div><h3 id="什么是-lid-命令" tabindex="-1">什么是 lid 命令？ <a class="header-anchor" href="#什么是-lid-命令" aria-label="Permalink to “什么是 lid 命令？”">​</a></h3><p>它显示用户的组或组的用户。显示有关包含用户名的组或组名称中包含的用户的信息。此命令需要管理员权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lid daygeek</span></span>
<span class="line"><span> adm(gid=4)</span></span>
<span class="line"><span> cdrom(gid=24)</span></span>
<span class="line"><span> sudo(gid=27)</span></span>
<span class="line"><span> dip(gid=30)</span></span>
<span class="line"><span> plugdev(gid=46)</span></span>
<span class="line"><span> lpadmin(gid=108)</span></span>
<span class="line"><span> daygeek(gid=1000)</span></span>
<span class="line"><span> sambashare(gid=124)</span></span></code></pre></div><h3 id="什么是-getent-命令" tabindex="-1">什么是 getent 命令？ <a class="header-anchor" href="#什么是-getent-命令" aria-label="Permalink to “什么是 getent 命令？”">​</a></h3><p><code>getent</code> 命令显示 Name Service Switch 库支持的数据库中的条目，它们在 <code>/etc/nsswitch.conf</code> 中配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group | grep daygeek</span></span>
<span class="line"><span>adm:x:4:syslog,daygeek</span></span>
<span class="line"><span>cdrom:x:24:daygeek</span></span>
<span class="line"><span>sudo:x:27:daygeek</span></span>
<span class="line"><span>dip:x:30:daygeek</span></span>
<span class="line"><span>plugdev:x:46:daygeek</span></span>
<span class="line"><span>lpadmin:x:118:daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span>
<span class="line"><span>sambashare:x:128:daygeek</span></span></code></pre></div><p>如果你只想打印关联的组名称，请在上面的命令中使用 <code>awk</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group | grep daygeek | awk -F: &#39;{print $1}&#39;</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>cdrom</span></span>
<span class="line"><span>sudo</span></span>
<span class="line"><span>dip</span></span>
<span class="line"><span>plugdev</span></span>
<span class="line"><span>lpadmin</span></span>
<span class="line"><span>daygeek</span></span>
<span class="line"><span>sambashare</span></span></code></pre></div><p>运行以下命令仅打印主群组信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span></code></pre></div><h3 id="什么是-grep-命令" tabindex="-1">什么是 grep 命令？ <a class="header-anchor" href="#什么是-grep-命令" aria-label="Permalink to “什么是 grep 命令？”">​</a></h3><p><code>grep</code> 代表 “<ruby>全局正则表达式打印<rt>global regular expression print</rt></ruby>”，它能打印文件匹配的模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/group</span></span>
<span class="line"><span>adm:x:4:syslog,daygeek</span></span>
<span class="line"><span>cdrom:x:24:daygeek</span></span>
<span class="line"><span>sudo:x:27:daygeek</span></span>
<span class="line"><span>dip:x:30:daygeek</span></span>
<span class="line"><span>plugdev:x:46:daygeek</span></span>
<span class="line"><span>lpadmin:x:118:daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span>
<span class="line"><span>sambashare:x:128:daygeek</span></span></code></pre></div><p>如果你只想打印关联的组名称，请在上面的命令中使用 <code>awk</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/group | awk -F: &#39;{print $1}&#39;</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>cdrom</span></span>
<span class="line"><span>sudo</span></span>
<span class="line"><span>dip</span></span>
<span class="line"><span>plugdev</span></span>
<span class="line"><span>lpadmin</span></span>
<span class="line"><span>daygeek</span></span>
<span class="line"><span>sambashare</span></span></code></pre></div><hr>`,38)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/prakash/"},{default:i(()=>[...s[2]||(s[2]=[a("Prakash Subramanian",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(g,[["render",h]]);export{f as __pageData,C as default};
